/* Reptiles & Amphibians set additions - cards appended after reptiles.js. Must stay directly after 'reptiles.js' in sets/manifest.js. */
(function () {
  var S = window.CardSets && window.CardSets.get('reptiles');
  if (!S) return;
  var extra = [{"name":"African Clawed Frog","rarity":"uncommon","id":"african-clawed-frog","subtitle":"Frog","details":"A fully aquatic frog of sub-Saharan Africa with flattened body, hind claws and eyes on top of its head. It rarely leaves water.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Bosco%20delle%20fate%20-%20Xenopus%20laevis.jpg?width=1024"},{"name":"Yellow-bellied Toad","rarity":"uncommon","id":"yellow-bellied-toad","subtitle":"Toad","details":"A small European toad with a warty grey back and a bright yellow belly, shown to predators by arching its body in warning.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Bombina%20variegata1b.jpg?width=1024"},{"name":"European Spadefoot","rarity":"uncommon","id":"european-spadefoot","subtitle":"Toad","details":"A plump European toad with a hard spade on each hind foot for digging backwards into sandy soil, where it spends the day.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Knoflookpad%20-%20common%20spadefoot%20-%20Pelobates%20fuscus%202.jpg?width=1024"},{"name":"Common Midwife Toad","rarity":"uncommon","id":"common-midwife-toad","subtitle":"Toad","details":"A small western European toad whose males carry strings of eggs wrapped around their hind legs until the tadpoles hatch.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Alytes%20obstetricans%20%284536438842%29.jpg?width=1024"},{"name":"Natterjack Toad","rarity":"uncommon","id":"natterjack-toad","subtitle":"Toad","details":"A European toad with a yellow stripe down its back and short legs, so it runs rather than hops. Its call carries over a kilometre.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Epidalea%20calamita%2001%20by-dpc.jpg?width=1024"},{"name":"European Green Toad","rarity":"uncommon","id":"european-green-toad","subtitle":"Toad","details":"A pale toad patterned with bright green blotches, found across Europe and western Asia in steppes, gardens and dry open ground.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Bufotes%20viridis%2004%2801%29.%20Khortytsia.jpg?width=1024"},{"name":"Colorado River Toad","rarity":"uncommon","id":"colorado-river-toad","subtitle":"Toad","details":"The largest native toad in the United States, a smooth-skinned olive toad of Sonoran Desert streams and rain-filled pools.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Incilius%20alvarius%20Stanton%201.JPG?width=1024"},{"name":"Great Plains Toad","rarity":"uncommon","id":"great-plains-toad","subtitle":"Toad","details":"A pale Great Plains toad with paired dark blotches and a loud, metallic breeding call, emerging after heavy summer rains.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Anaxyrus%20cognatus%2C%20Great%20Plains%20Toad%2C%20Tamaulipas.jpg?width=1024"},{"name":"Woodhouse's Toad","rarity":"uncommon","id":"woodhouses-toad","subtitle":"Toad","details":"A widespread western North American toad with a pale belly and a white stripe down its back, calling from ponds and ditches.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Anaxyrus%20woodhousii.jpg?width=1024"},{"name":"Oak Toad","rarity":"uncommon","id":"oak-toad","subtitle":"Toad","details":"One of North America's smallest toads, at about 3 cm, from pine flatwoods of the southeast, with a bold pale back stripe.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Oak%20Toad%20-%20Anaxyrus%20quercicus%2C%20Babcock-Webb%20Wildlife%20Management%20Area%2C%20Punta%20Gorda%2C%20Florida.jpg?width=1024"},{"name":"Smoky Jungle Frog","rarity":"uncommon","id":"smoky-jungle-frog","subtitle":"Frog","details":"A large, powerful frog of Central and South American rainforests. Males develop swollen arms and chest spines for breeding.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Bull%20frog%20%28Leptodactylus%20pentadactylus%29.jpg?width=1024"},{"name":"Riobamba Marsupial Frog","rarity":"uncommon","id":"riobamba-marsupial-frog","subtitle":"Frog","details":"An Ecuadorian tree frog whose female carries her eggs in a pouch on her back, releasing tadpoles into high mountain pools.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Gastrotheca%20riobambae%20192021825.jpg?width=1024"},{"name":"Northern Leopard Frog","rarity":"uncommon","id":"northern-leopard-frog","subtitle":"Frog","details":"A green frog with neat dark leopard spots edged in pale haloes, found across northern North America in marshes and ponds.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Frog%20Lithobates%20pipiens%20RBG.jpg?width=1024"},{"name":"Wood Frog","rarity":"uncommon","id":"wood-frog","subtitle":"Frog","details":"A brown frog with a dark robber's mask, breeding in northern woodland pools. It can survive being partly frozen in winter.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/063%20366%20-%20Wood%20Frog%20-%20Lithobates%20sylvaticus%20with%20Northern%20Frog-biting%20Mosquito%20-%20Culex%20territans%2C%20Lake%20Accotink%20Park%2C%20Springfield%2C%20Virginia%2C%20March%203%2C%202024%20%2853565225117%29.jpg?width=1024"},{"name":"Pacific Tree Frog","rarity":"uncommon","id":"pacific-tree-frog","subtitle":"Frog","details":"A small tree frog of western North America that ranges from green to brown and changes shade, with a dark stripe through the eye.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Pacific%20Tree%20Frog%20%28Pseudacris%20regilla%29%20-%20Flickr%20-%20GregTheBusker.jpg?width=1024"},{"name":"Pig Frog","rarity":"uncommon","id":"pig-frog","subtitle":"Frog","details":"A large, fully aquatic frog of southeastern swamps and lakes, named because its deep breeding call sounds like a pig grunting.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Pig%20Frog%20%28Lithobates%20grylio%29.jpg?width=1024"},{"name":"Emerald Glass Frog","rarity":"uncommon","id":"emerald-glass-frog","subtitle":"Frog","details":"A bright green glass frog of Central American streams, with dark spots and, in males, a sharp little spine on the upper arm.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Centrolene%20prosoblepon02.jpg?width=1024"},{"name":"Painted Reed Frog","rarity":"uncommon","id":"painted-reed-frog","subtitle":"Frog","details":"A small, highly variable reed frog of eastern and southern Africa, marbled or striped, calling from reeds around wetlands.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Hyperolius%20marmoratus.jpg?width=1024"},{"name":"Dyeing Poison Dart Frog","rarity":"uncommon","id":"dyeing-poison-dart-frog","subtitle":"Frog","details":"A large, boldly patterned dart frog of northern South America, in yellow, blue or white forms with bold black markings and spots.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Dendrobates%20tinctorius%2C%20Blue%20poison%20dart%20frog.jpg?width=1024"},{"name":"Anthony's Poison Arrow Frog","rarity":"uncommon","id":"anthonys-poison-arrow-frog","subtitle":"Frog","details":"A red-striped dart frog of Ecuador and Peru, with pale side stripes. Males carry tadpoles on their backs to forest streams.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Epipedobates%20anthonyi%20Tierra%20Alta%202026-09-10%20for%20Wikimedia.jpg?width=1024"},{"name":"Mimic Poison Dart Frog","rarity":"uncommon","id":"mimic-poison-dart-frog","subtitle":"Frog","details":"A tiny Peruvian dart frog that copies the colour patterns of three other poison frogs in different parts of its wide range.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Ranitomeya%20imitator%20%27Chazuta%27.jpg?width=1024"},{"name":"Bumblebee Toad","rarity":"uncommon","id":"bumblebee-toad","subtitle":"Toad","details":"A tiny black toad with yellow spots and red feet from Argentina and Uruguay, coloured like the bumblebee it is named for.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Melanophryniscus%20stelzneri.jpg?width=1024"},{"name":"Cranwell's Horned Frog","rarity":"uncommon","id":"cranwells-horned-frog","subtitle":"Frog","details":"A chunky, wide-mouthed horned frog of the dry Chaco, mostly brown and tan, that sits buried in leaf litter waiting for passing prey.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Ceratophrys%20cranwelli%20703695438.jpg?width=1024"},{"name":"Red-spotted Toad","rarity":"uncommon","id":"red-spotted-toad","subtitle":"Toad","details":"A small, flattened toad of rocky southwestern streams and deserts, with a round snout and fine reddish spots on its back.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Anaxyrus%20punctatus%2C%20Red-spotted%20Toad%2C%20Tamaulipas.jpg?width=1024"},{"name":"Painted Turtle","rarity":"uncommon","id":"painted-turtle","subtitle":"Turtle","details":"Brightly marked North American pond turtle with a smooth olive shell, red shell edges and yellow stripes along its head and legs.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Painted%20Turtle%20%28Chrysemys%20picta%29%20in%20grass%2C%20Northern%20Illinois%20-%20June%2C%202025.jpg?width=1024"},{"name":"Red-eared Slider","rarity":"uncommon","id":"red-eared-slider","subtitle":"Turtle","details":"Pond slider of the southern United States and northern Mexico, with webbed feet, a patterned shell and bold streaks on its head.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Trachemys%20scripta%20elegans%20partially%20submerged%2C%20three%20quarter%20view.jpg?width=1024"},{"name":"Eastern Box Turtle","rarity":"uncommon","id":"eastern-box-turtle","subtitle":"Turtle","details":"North American land box turtle with a tall hinged shell it can close completely, patterned in yellow or orange over dark brown.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Terrapene%20carolina%20ssp.%20carolina%20-%20Eastern%20Box%20Turtle%20%288-11-23%29%2002.jpg?width=1024"},{"name":"Ornate Box Turtle","rarity":"uncommon","id":"ornate-box-turtle","subtitle":"Turtle","details":"Prairie box turtle of central North America, its domed dark shell painted with pale radiating lines on every single scute.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Ornate%20Box%20Turtle%20%28Terrapene%20ornata%20ornata%29%20%28a9f6513e-32c8-46b8-9e3b-775b7d51c35d%29.jpg?width=1024"},{"name":"Spotted Turtle","rarity":"uncommon","id":"spotted-turtle","subtitle":"Turtle","details":"Small North American marsh turtle, its smooth black shell and head sprinkled with round yellow spots, one pattern per turtle.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Spotted%20Turtle%20-%20Clemmys%20guttata.jpg?width=1024"},{"name":"Bog Turtle","rarity":"uncommon","id":"bog-turtle","subtitle":"Turtle","details":"Tiny North American bog turtle, barely ten centimetres long, with a bright orange patch on each side of its dark head and short neck.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Bog%20Turtle%20-%20DPLA%20-%2044176be34681ca90c981f1648dbc79f1.jpg?width=1024"},{"name":"Chicken Turtle","rarity":"uncommon","id":"chicken-turtle","subtitle":"Turtle","details":"Southeastern United States pond turtle with a finely netted, rough-textured shell pattern and a long neck with pale stripes.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Chicken%20turtle%20%28Deirochelys%20reticularia%29%20Florida%20Sub%20adult.jpg?width=1024"},{"name":"Florida Softshell Turtle","rarity":"uncommon","id":"florida-softshell-turtle","subtitle":"Turtle","details":"Large softshell turtle of Florida lakes, canals and marshes, with a flat leathery shell, tubular snout and powerful webbed front feet.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Florida-Weichschildkr%C3%B6te%20%28Apalone%20ferox%2C%20Syn.%20Trionyx%20ferox%29%20in%20einem%20Feuchtgebiet.jpg?width=1024"},{"name":"Smooth Softshell Turtle","rarity":"uncommon","id":"smooth-softshell-turtle","subtitle":"Turtle","details":"Smooth-shelled softshell of large North American rivers, lacking the spines of its relatives, with a pale underside and long neck.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Apalone%20mutica%20mutica%2C%20Seitenansicht.jpg?width=1024"},{"name":"Argentine Snake-necked Turtle","rarity":"uncommon","id":"argentine-snake-necked-turtle","subtitle":"Turtle","details":"Side-necked turtle of South American streams, hiding its long neck sideways beneath a rough, dark, strongly keeled shell.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Hydromedusa%20tectifera%20en%20Punta%20Lara%2001.jpg?width=1024"},{"name":"Twist-necked Turtle","rarity":"uncommon","id":"twist-necked-turtle","subtitle":"Turtle","details":"Small Amazon stream turtle whose very flat head twists sideways under its shell, marked with bold orange and black bands.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Platemys%20platycephala%20Manu%20dorsla.jpg?width=800"},{"name":"Mary River Turtle","rarity":"uncommon","id":"mary-river-turtle","subtitle":"Turtle","details":"Large river turtle of Queensland's Mary River, with a streamlined shell, chin barbels and a very long, thick muscular tail.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Elusor%20macrurus%2071753055.jpg?width=1024"},{"name":"Krefft's River Turtle","rarity":"uncommon","id":"kreffts-river-turtle","subtitle":"Turtle","details":"Widespread Australian river turtle with a smooth oval shell, a pale stripe running through the eye and strongly webbed hind feet.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Emydura%20macquarii%20ssp.%20krefftii%20SF26041-1.jpg?width=1024"},{"name":"Striped Mud Turtle","rarity":"uncommon","id":"striped-mud-turtle","subtitle":"Turtle","details":"Small mud turtle of Florida wetlands, with three pale lengthwise stripes over its smooth dark shell and a hinged plastron.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Kinosternon%20baurii%20329750171.jpg?width=1024"},{"name":"Common Musk Turtle","rarity":"uncommon","id":"common-musk-turtle","subtitle":"Turtle","details":"Small North American musk turtle of slow waters, with a domed shell, two pale head stripes and barbels beneath its chin.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Common%20Musk%20Turtle.jpg?width=1024"},{"name":"European Pond Turtle","rarity":"uncommon","id":"european-pond-turtle","subtitle":"Turtle","details":"Pond turtle found across Europe east to Central Asia, its dark shell and skin flecked with yellow spots and fine radiating lines.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/European%20pond%20turtle%20%28Emys%20orbicularis%29.jpg?width=1024"},{"name":"Siamese Crocodile","rarity":"uncommon","id":"siamese-crocodile","subtitle":"Crocodile","details":"A medium-sized crocodile of Southeast Asian rivers and swamps, reaching about 3 metres, with a fairly broad snout and crested scales.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Siamese%20Crocodiles.JPG?width=1024"},{"name":"Philippine Crocodile","rarity":"uncommon","id":"philippine-crocodile","subtitle":"Crocodile","details":"A small crocodile found only in the Philippines, in upland streams and small lakes, reaching about 3 metres, with a broad snout.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Crocodylus%20mindorensis%20by%20Gregg%20Yan%2001.jpg?width=1024"},{"name":"African Dwarf Crocodile","rarity":"uncommon","id":"african-dwarf-crocodile","subtitle":"Crocodile","details":"The smallest living crocodile, from West and Central African rainforest streams, reaching about 1.8 metres, with a short, blunt snout.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Osteolaemus%20tetraspis%20-%20Karlsruhe%20Zoo%2001.jpg?width=1024"},{"name":"West African Slender-snouted Crocodile","rarity":"uncommon","id":"west-african-slender-snouted-crocodile","subtitle":"Crocodile","details":"A slender-snouted crocodile of West African rivers and lagoons, reaching about 3 metres, feeding largely on fish and aquatic prey.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Crocodylus%20cataphractus%200zz.jpg?width=1024"},{"name":"Morelet's Crocodile","rarity":"uncommon","id":"morelets-crocodile","subtitle":"Crocodile","details":"A small to medium crocodile of Central American swamps and lagoons, reaching about 3 metres, with a short, unusually broad snout.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Morelets.crocodile.arp.jpg?width=1024"},{"name":"Spectacled Caiman","rarity":"uncommon","id":"spectacled-caiman","subtitle":"Caiman","details":"A small caiman of Central and South American wetlands, reaching about 2.5 metres, named for the bony ridge between its eyes.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Spectacled%20caiman%20in%20Costa%20Rica%2001.jpg?width=1024"},{"name":"Australian Freshwater Crocodile","rarity":"uncommon","id":"australian-freshwater-crocodile","subtitle":"Crocodile","details":"A slender-snouted crocodile of northern Australian rivers and billabongs, reaching about 3 metres, feeding mainly on fish.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Fresh%20Water%20Crocodile%20%28Crocodylus%20johnstoni%29%20%288697802314%29.jpg?width=1024"},{"name":"Spotted Salamander","rarity":"uncommon","id":"spotted-salamander","subtitle":"Salamander","details":"A glossy black mole salamander marked with bright yellow spots, it returns each spring to woodland pools across eastern North America.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Spotted%20Salamander%2C%20Cantley%2C%20Quebec.jpg?width=1024"},{"name":"Marbled Salamander","rarity":"uncommon","id":"marbled-salamander","subtitle":"Salamander","details":"A boldly banded mole salamander of eastern woodlands, females lay their eggs in dry pond beds in autumn and guard them until rain.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Marbled%20Salamander%20%28Ambystoma%20opacum%29%20-%20Flickr%20-%20GregTheBusker.jpg?width=1024"},{"name":"Alpine Salamander","rarity":"uncommon","id":"alpine-salamander","subtitle":"Salamander","details":"A jet-black salamander of high European Alps meadows, it gives birth to fully formed young after one of the longest amphibian pregnancies.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Salamandra%20atra%20Bizau%2002.jpg?width=1024"},{"name":"Lesser Siren","rarity":"uncommon","id":"lesser-siren","subtitle":"Salamander","details":"A slender, eel-like aquatic salamander of muddy southern ponds and ditches, it can estivate in a cocoon when its wetland dries out.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Lesser%20Siren%20%28Siren%20intermedia%29%20-%20Flickr%20-%20GregTheBusker.jpg?width=1024"},{"name":"Three-toed Amphiuma","rarity":"uncommon","id":"three-toed-amphiuma","subtitle":"Salamander","details":"A very long, eel-like salamander of southeastern swamps, it has two tiny pairs of legs, each tipped with three toes, and a strong bite.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Three-Toed%20Amphiuma%20%28Amphiuma%20tridactylum%29%20%2817011985960%29.jpg?width=1024"},{"name":"Rough-skinned Newt","rarity":"uncommon","id":"rough-skinned-newt","subtitle":"Newt","details":"A stocky orange-bellied newt of Pacific coastal forests, named for its grainy skin, it walks woodlands and breeds in quiet ponds.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Rough-skinned%20Newt%20Taricha%20granulosa%20%2833731812646%29.jpg?width=1024"},{"name":"Iberian Ribbed Newt","rarity":"uncommon","id":"iberian-ribbed-newt","subtitle":"Newt","details":"The largest European newt, this Iberian species can push the sharp tips of its ribs through bumps along its flanks when threatened.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Pleurodeles%20waltl%2003%20by-dpc.jpg?width=1024"},{"name":"Emperor Newt","rarity":"uncommon","id":"emperor-newt","subtitle":"Newt","details":"A warty, orange-and-black newt of mountain forests in Yunnan, China, it breeds in still ponds and forages on the forest floor.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Emperor%20newt%20yunnan%20china.jpg?width=1024"},{"name":"Yellow-striped Caecilian","rarity":"uncommon","id":"yellow-striped-caecilian","subtitle":"Caecilian","details":"A limbless, burrowing amphibian of Southeast Asia, this caecilian has a bold yellow stripe along each side of its dark body.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Ichthyophis%20kohtaoensis%20129267228.jpg?width=1024"},{"name":"Corn Snake","rarity":"common","id":"corn-snake","subtitle":"Snake","details":"A slender orange rat snake of the southeastern United States with black-edged red blotches, an excellent climber common around farms and barns.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Kornnatter%20%28Pantherophis%20guttatus%29%2C%20Seitenansicht.jpg?width=1024"},{"name":"Eastern Rat Snake","rarity":"common","id":"eastern-rat-snake","subtitle":"Snake","details":"A large, dark rat snake of eastern North American forests and farmland, an expert climber that often rests coiled on branches and rock ledges.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Complex%20Pantherophis%20alleghaniensis%20-%20Eastern%20%26%20Gray%20Ratsnake%20Complex%2001.jpg?width=1024"},{"name":"Western Rat Snake","rarity":"common","id":"western-rat-snake","subtitle":"Snake","details":"A big, dark rat snake of central North America, at home in barns, cliffs and woodland, where its climbing skill takes it high into the trees.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Sunlit%20Snake.jpg?width=1024"},{"name":"California Kingsnake","rarity":"common","id":"california-kingsnake","subtitle":"Snake","details":"A glossy kingsnake of the American west coast, banded or striped in black and white, famous for hunting rattlesnakes in rocky scrub and grass.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Lampropeltis%20californiae.jpg?width=1024"},{"name":"Eastern Kingsnake","rarity":"common","id":"eastern-kingsnake","subtitle":"Snake","details":"A shiny black kingsnake of the eastern United States with thin white chain-like crossbands, a powerful constrictor of woodland and wetlands.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Lampropeltis%20getula%20Stanton%201.jpg?width=1024"},{"name":"Speckled Kingsnake","rarity":"common","id":"speckled-kingsnake","subtitle":"Snake","details":"A black kingsnake of the Mississippi valley and Gulf coast, each scale flecked with yellow-white so the whole snake seems dusted with stars.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Speckled%20Kingsnake%20%28Lampropeltis%20holbrooki%29%2C%20Austin%20Co.%2C%20TX%2C%202022.jpg?width=1024"},{"name":"Mexican Black Kingsnake","rarity":"common","id":"mexican-black-kingsnake","subtitle":"Snake","details":"A jet-black kingsnake of northwestern Mexico and Arizona, an active daytime hunter of desert scrub, farmland and rocky foothill country.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Schwarze%20Kettennatter.jpg?width=1024"},{"name":"Eastern Milksnake","rarity":"common","id":"eastern-milksnake","subtitle":"Snake","details":"A small, blotched kingsnake of eastern fields and barns, grey to tan with reddish-brown saddles, long mistaken for a young rat snake by many.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Lampropeltis%20triangulum%20293880080.jpg?width=1024"},{"name":"Scarlet Kingsnake","rarity":"common","id":"scarlet-kingsnake","subtitle":"Snake","details":"A small, brilliant tricoloured kingsnake of southeastern pine flatwoods, its red, black and yellow rings mimicking the coral snake's warning.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Scarlet%20003.JPG?width=1024"},{"name":"Gopher Snake","rarity":"common","id":"gopher-snake","subtitle":"Snake","details":"A large, yellowish snake of western North America that hisses and vibrates its tail in dry leaves, convincingly imitating a rattlesnake.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Gophersnake%20Pituophis%20catenifer%2020260330.jpg?width=1024"},{"name":"Common Garter Snake","rarity":"common","id":"common-garter-snake","subtitle":"Snake","details":"One of North America's most widespread snakes, striped yellow along a dark back, found in gardens, marshes and meadows from Canada to Mexico.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Thamnophis%20sirtalis%20Stanton%202.jpg?width=1024"},{"name":"Eastern Ribbon Snake","rarity":"common","id":"eastern-ribbon-snake","subtitle":"Snake","details":"A slender, striped waterside snake of eastern North America with a clean white spot before the eye, hunting frogs and fish along marsh edges.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Eastern%20ribbonsnake%20huntley%20meadows%207.20.24%20DSC%203124-topaz-denoiseraw.jpg?width=1024"},{"name":"Western Terrestrial Garter Snake","rarity":"common","id":"western-terrestrial-garter-snake","subtitle":"Snake","details":"A variable garter snake of western mountains and valleys, equally at home on dry hillsides and lake shores, and an unusually strong swimmer.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Thamnophis%20elegans%20terrestris.jpg?width=800"},{"name":"Checkered Garter Snake","rarity":"common","id":"checkered-garter-snake","subtitle":"Snake","details":"A chequered garter snake of the southwestern United States and Mexico, its neat checkerboard of dark squares broken by a pale back stripe.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Thamnophis%20marcianus%20186822611.jpg?width=1024"},{"name":"Plains Garter Snake","rarity":"common","id":"plains-garter-snake","subtitle":"Snake","details":"A striped garter snake of central North American prairies and wetlands, orange-yellow along the back, emerging early in cold spring weather.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Thamnophis%20radix%20266361330.jpg?width=1024"},{"name":"Eastern Racer","rarity":"common","id":"eastern-racer","subtitle":"Snake","details":"A long, matte black or blue-grey snake of eastern fields and forest edges, fast and alert by day, hunting with its head raised like a periscope.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Coluber%20constrictor%20-%20North%20American%20Racer%2001.jpg?width=1024"},{"name":"Rough Green Snake","rarity":"common","id":"rough-green-snake","subtitle":"Snake","details":"A bright green, slender snake of eastern shrubs and vines, its rough-looking keeled scales and gentle manner making it nearly invisible in leaves.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Opheodrys%20aestivus%20-%20rough%20green%20snake%20cropped.jpg?width=1024"},{"name":"Smooth Green Snake","rarity":"common","id":"smooth-green-snake","subtitle":"Snake","details":"A small, smooth-scaled green snake of northern meadows and marshes, feeding almost entirely on insects and spiders in cool grassland habitat.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Smooth%20Green%20Snake%20%28Opheodrys%20vernalis%29.jpg?width=1024"},{"name":"Dekay's Brownsnake","rarity":"common","id":"dekays-brownsnake","subtitle":"Snake","details":"A tiny, secretive brown snake of eastern gardens and lots, marked with paired dark spots, feeding on slugs and earthworms in damp litter.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Storeria%20dekayi%201.jpg?width=1024"},{"name":"Red-bellied Snake","rarity":"common","id":"red-bellied-snake","subtitle":"Snake","details":"A small northern snake, brown or grey above and brilliant red below, living under logs and leaves in forests and bogs across eastern America.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Storeria%20occipitomaculata%20Stanton.jpg?width=1024"},{"name":"Ring-necked Snake","rarity":"common","id":"ring-necked-snake","subtitle":"Snake","details":"A small, slate-grey snake with a golden belly and a neat neck ring, secretive under stones and bark in forests across much of North America.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Diadophis%20punctatus1.jpg?width=1024"},{"name":"Eastern Worm Snake","rarity":"common","id":"eastern-worm-snake","subtitle":"Snake","details":"A tiny, glossy pink-bellied burrower of eastern forests, feeding almost wholly on earthworms and rarely seen except under logs after rain.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Carphophis%20amoenus%20amoenus.jpg?width=1024"},{"name":"Queen Snake","rarity":"common","id":"queen-snake","subtitle":"Snake","details":"A slender brown watersnake of eastern streams that specialises in eating freshly moulted crayfish, basking on branches overhanging the water.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Regina%20septemvittata.jpg?width=1024"},{"name":"Northern Watersnake","rarity":"common","id":"northern-watersnake","subtitle":"Snake","details":"A heavy, variable watersnake of eastern lakes and rivers, dark-banded when young, often plain brown in age, and a tireless hunter of fish.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Nerodia%20sipedon%20Stanton%201.jpg?width=1024"},{"name":"Banded Watersnake","rarity":"common","id":"banded-watersnake","subtitle":"Snake","details":"A broad-banded watersnake of southeastern swamps and bayous, spending its days among cypress roots and its nights hunting frogs and fish.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Nerodia%20fasciata%20confluens%20321616031.jpg?width=1024"},{"name":"Brown Watersnake","rarity":"common","id":"brown-watersnake","subtitle":"Snake","details":"A heavy watersnake of southeastern rivers and swamps, often seen basking on overhanging limbs and dropping into dark water at any disturbance.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Brown%20Water%20Snake.jpg?width=1024"},{"name":"Diamondback Watersnake","rarity":"common","id":"diamondback-watersnake","subtitle":"Snake","details":"North America's largest watersnake, a heavy chain-patterned species of central rivers and lakes, hunting fish in shallow, weedy margins at night.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Nerodia%20rhombifer%20252324167.jpg?width=1024"},{"name":"Plain-bellied Watersnake","rarity":"common","id":"plain-bellied-watersnake","subtitle":"Snake","details":"A plain, unpatterned watersnake of southeastern wetlands as an adult, wandering far from water across fields and woods on warm summer nights.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Plain-bellied%20Watersnake%20%28Nerodia%20erythrogaster%29%2C%20Chambers%20Co.%2C%20TX%2C%2026%20July%202013.jpg?width=1024"},{"name":"Grass Snake","rarity":"common","id":"grass-snake","subtitle":"Snake","details":"A familiar olive-green snake of European wetlands and damp meadows, marked with a yellow collar, playing dead convincingly when it is caught.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/The%20Grass%20Snake%20-%20Natrix%20natrix.jpg?width=1024"},{"name":"Barred Grass Snake","rarity":"common","id":"barred-grass-snake","subtitle":"Snake","details":"A grass snake of western Europe, including Britain, recognised by the dark bars along its flanks and its love of ponds, ditches and compost heaps.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Barrenringelnatter%20Natrix%20helvetica.jpg?width=1024"},{"name":"Dice Snake","rarity":"common","id":"dice-snake","subtitle":"Snake","details":"A chequered watersnake of southern Europe and western Asia, spending long hours hunting fish in rivers and lakes and basking on stony banks.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Natrix%20tessellata%20-%20dice%20snake.jpg?width=1024"},{"name":"Viperine Snake","rarity":"common","id":"viperine-snake","subtitle":"Snake","details":"A small, viper-patterned watersnake of southwestern Europe and North Africa, harmless despite its zigzags, hunting frogs and fish in streams.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Viperine%20water%20snake%20%28Natrix%20maura%29.jpg?width=1024"},{"name":"Smooth Snake","rarity":"common","id":"smooth-snake","subtitle":"Snake","details":"A small, secretive snake of European heaths and sunny slopes, grey-brown with dark spots, slipping through dense heather after lizards and rodents.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/CoronellaAustriaca1.jpg?width=1024"},{"name":"Aesculapian Snake","rarity":"common","id":"aesculapian-snake","subtitle":"Snake","details":"A large, olive-brown climbing snake of southern and central European woodland, long linked with healing temples in Greek and Roman tradition.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Zamenis%20longissimus.jpg?width=1024"},{"name":"Ladder Snake","rarity":"common","id":"ladder-snake","subtitle":"Snake","details":"A Mediterranean snake named for the ladder-like pattern on juveniles' backs; adults fade to plain olive with two dark stripes along the body.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Benny%20Trapp%20Rhinechis%20scalaris%20Jugendzeichnung%20Portugal.jpg?width=1024"},{"name":"Four-lined Snake","rarity":"common","id":"four-lined-snake","subtitle":"Snake","details":"One of Europe's largest snakes, a yellow-brown rat snake of Mediterranean scrub and ruins with four dark lines running the length of its body.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/E%20quatuorlineata.jpg?width=1024"},{"name":"Leopard Snake","rarity":"common","id":"leopard-snake","subtitle":"Snake","details":"A beautifully blotched snake of southern European rocky country, its reddish spots on grey recalling a leopard and making it a prized sighting.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Zamenis%20situla%20181473159.jpg?width=1024"},{"name":"Horseshoe Whip Snake","rarity":"common","id":"horseshoe-whip-snake","subtitle":"Snake","details":"A fast, slender snake of Iberia and North Africa with a horseshoe mark on the neck, hunting lizards across sun-baked scrub and stone walls.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Hemorrhois%20hippocrepis%20in%20Portugal.jpg?width=1024"},{"name":"Western Whip Snake","rarity":"common","id":"western-whip-snake","subtitle":"Snake","details":"A very fast, greenish-black snake of southern European hillsides, hunting lizards by sight in open scrub and vanishing into cover in a flash.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Hierophis%20viridiflavus%20%28P%C3%A9rign%C3%A9%29%2029082023%2002.jpg?width=1024"},{"name":"Western Green Lizard","rarity":"common","id":"western-green-lizard","subtitle":"Lizard","details":"A big green lizard of southwestern Europe, close kin to the eastern species. Males turn blue-throated in the breeding season.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Lacerta%20bilineata%20%28Luitr%C3%A9-Dompierre%29%2001052025%2002.jpg?width=1024"},{"name":"Sand Lizard","rarity":"common","id":"sand-lizard","subtitle":"Lizard","details":"A stocky European lizard of heaths and dunes. In spring the males turn brilliant green along the flanks to court females.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Lacerta%20agilis%20224716148.jpg?width=1024"},{"name":"Common Lizard","rarity":"common","id":"common-lizard","subtitle":"Lizard","details":"Europe's most widespread lizard, living farther north than any other reptile. It gives birth to live young in cool climates.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Waldeidechse%20Zootoca%20vivipara%201.jpg?width=1024"},{"name":"Italian Wall Lizard","rarity":"common","id":"italian-wall-lizard","subtitle":"Lizard","details":"A variable wall lizard of Italy and the Mediterranean, common on ruins and stone walls. Island forms can be black with blue spots.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Italian%20wall%20lizard%20%28Podarcis%20siculus%20siculus%29.jpg?width=1024"},{"name":"Common Wall Lizard","rarity":"common","id":"common-wall-lizard","subtitle":"Lizard","details":"A nimble European lizard of walls, rocks and railway banks. Several island populations show striking colour variations. It is nimble.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/L%C3%A9zard%20des%20murailles%20%28Podarcis%20muralis%29%20%288%29.jpg?width=1024"},{"name":"Aegean Wall Lizard","rarity":"common","id":"aegean-wall-lizard","subtitle":"Lizard","details":"A wall lizard of Greece and the Aegean islands, often boldly patterned. It thrives on dry, rocky islets and coastal cliffs.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Podarcis%20erhardii%20-%20Erhard%27s%20wall%20lizard%20in%20Albania.jpg?width=1024"},{"name":"Iberian Wall Lizard","rarity":"common","id":"iberian-wall-lizard","subtitle":"Lizard","details":"A small wall lizard of Spain and Portugal, common on stone walls and mountain rocks from the coast to high elevations. It basks often.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Podarcis%20hispanicus%20DT%20-ES%20Cazorla%20PN-%20%281%29%20%2820122138114%29.jpg?width=1024"},{"name":"Balkan Green Lizard","rarity":"common","id":"balkan-green-lizard","subtitle":"Lizard","details":"The largest green lizard of the Balkans, reaching well over a metre with its tail. It climbs into shrubs to bask and hunt.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Lacerta%20trilineata.jpg?width=1024"},{"name":"Ocellated Lizard","rarity":"common","id":"ocellated-lizard","subtitle":"Lizard","details":"Europe's largest lizard, a muscular Iberian species with blue eye-spots along its flanks. It shelters in burrows and rock piles.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Benny%20Trapp%20Timon%20lepidus%20Jugendzeichnung%20Spanien.jpg?width=1024"},{"name":"Sheltopusik","rarity":"common","id":"sheltopusik","subtitle":"Lizard","details":"A large, legless glass lizard of southern Europe and central Asia, also called the European glass lizard. It can exceed a metre.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/K.%20Kalaentzis%20Pseudopus%20apodus.jpg?width=1024"},{"name":"Slow Worm","rarity":"common","id":"slow-worm","subtitle":"Lizard","details":"A legless, burrowing lizard of Europe that looks like a small snake but blinks and sheds its tail like other lizards. It hunts slugs and earthworms.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Anguis%20fragilis%20Padalec%20zwyczajny%202018-06-24%2003.jpg?width=1024"},{"name":"Eastern Glass Lizard","rarity":"common","id":"eastern-glass-lizard","subtitle":"Lizard","details":"A long, legless lizard of the southeastern US coastal plain. Its stiff body and grooved sides set it apart from true snakes.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Ophisaurus%20ventralis%20flirting.jpg?width=1024"},{"name":"Southern Alligator Lizard","rarity":"common","id":"southern-alligator-lizard","subtitle":"Lizard","details":"A long-bodied western North American lizard with armoured scales and a fold of skin along each side of the body. It climbs low shrubs well.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Elgaria%20multicarinata%20126205020.jpg?width=1024"},{"name":"Northern Alligator Lizard","rarity":"common","id":"northern-alligator-lizard","subtitle":"Lizard","details":"A Pacific Northwest lizard of damp forests and meadows. Females give birth to live young in late summer and autumn. It shelters under bark and logs.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/USFWS%20elgaria%20coerulea%20%2823554097310%29.jpg?width=1024"},{"name":"Texas Alligator Lizard","rarity":"common","id":"texas-alligator-lizard","subtitle":"Lizard","details":"A large, long-tailed lizard of Texas and Mexican rocky canyons. It climbs well and shelters in crevices and leaf litter.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Gerrhonotus%20infernalis%20106841753.jpg?width=1024"},{"name":"Emerald Swift","rarity":"common","id":"emerald-swift","subtitle":"Lizard","details":"A brilliant green spiny lizard of Central American highlands. Males are emerald above with turquoise scales on the throat.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Emerald%20swift%20%28Sceloporus%20malachiticus%29%20Finca%20El%20Pilar.jpg?width=1024"},{"name":"Texas Spiny Lizard","rarity":"common","id":"texas-spiny-lizard","subtitle":"Lizard","details":"A rough-scaled Texas lizard of trees, fences and rock walls. Its bark-like patterning makes a basking adult hard to spot.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Sceloporus%20olivaceus%20365130763.jpg?width=1024"},{"name":"Crevice Spiny Lizard","rarity":"common","id":"crevice-spiny-lizard","subtitle":"Lizard","details":"A flattened spiny lizard of the Southwest that wedges into rock crevices, inflating its body so predators cannot pull it free.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Crevice%20spiny%20lizard%20%28Sceloporus%20poinsettii%29%2C%20Mason%20County%2C%20Texas%2C%20USA%20%289%20May%202014%29.jpg?width=1024"},{"name":"Clark's Spiny Lizard","rarity":"common","id":"clarks-spiny-lizard","subtitle":"Lizard","details":"A large spiny lizard of Arizona and Sonora with a dark collar and cross-banded back. It basks high on boulders and saguaros.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Sceloporus%20clarkii.jpeg?width=1024"},{"name":"Granite Spiny Lizard","rarity":"common","id":"granite-spiny-lizard","subtitle":"Lizard","details":"A dark, granite-dwelling lizard of southern California and Baja. Males show purple on the back and bright blue belly patches.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Sceloporus%20orcutti%20-%20Granite%20Spiny%20Lizard%20%2810304883116%29.jpg?width=1024"},{"name":"Desert Spiny Lizard","rarity":"common","id":"desert-spiny-lizard","subtitle":"Lizard","details":"A big, bold spiny lizard of Sonoran Desert country. Breeding males flush yellow-green with vivid blue throats and bellies.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/DESERT%20SPINY%20LIZARD%20Sceloporus%20magister%20-%20Flickr%20-%20gailhampshire%20%281%29.jpg?width=1024"},{"name":"Sagebrush Lizard","rarity":"common","id":"sagebrush-lizard","subtitle":"Lizard","details":"A small spiny lizard of western sagebrush country. It is one of the most common lizards of high desert and open pine forest.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Sagebrush%20lizard%20Sceloporus%20graciosus%20Grand%20Canyon%209699.jpg?width=1024"},{"name":"Western Skink","rarity":"common","id":"western-skink","subtitle":"Lizard","details":"A smooth, shiny western North American skink. Juveniles carry a bright blue tail that distracts predators from the body.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Juvenile%20Western%20Skink%20%28Plestiodon%20skiltonianus%29.JPG?width=1024"},{"name":"Ground Skink","rarity":"common","id":"ground-skink","subtitle":"Lizard","details":"North America's smallest reptile, a tiny leaf-litter skink of the Southeast also called the little brown skink. It slips through litter almost unseen.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Little%20brown%20skink%20or%20ground%20skink%20scincella%20lateralis.jpg?width=1024"},{"name":"Southeastern Five-lined Skink","rarity":"common","id":"southeastern-five-lined-skink","subtitle":"Lizard","details":"A striped skink of the southeastern US coastal plain, very like its five-lined cousin but favouring drier, sandier ground.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Plestiodon%20inexpectatus%20123619813.jpg?width=1024"},{"name":"African Fire Skink","rarity":"common","id":"african-fire-skink","subtitle":"Lizard","details":"A glossy African skink with fiery red and gold flanks and a blue tail. It burrows in the leaf litter of West African forests.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Riopa%20fernandi.jpg?width=1024"},{"name":"Delicate Garden Skink","rarity":"common","id":"delicate-garden-skink","subtitle":"Lizard","details":"A tiny, iridescent Australian garden skink that lays communal egg clutches under logs and stones in summer. It hunts tiny insects among fallen leaves.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Lampropholis%20delicata%20%2823883081112%29.jpg?width=1024"},{"name":"Rainbow Skink","rarity":"common","id":"rainbow-skink","subtitle":"Lizard","details":"An African skink whose males flush orange-headed and blue-tailed in breeding season. It basks on rocks and tree trunks. It basks daily.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Rainbow%20skink%20%28Trachylepis%20margaritifera%29%20female%20Kruger.jpg?width=1024"},{"name":"Common Sun Skink","rarity":"common","id":"common-sun-skink","subtitle":"Lizard","details":"A widespread Asian skink, golden-brown and glossy, that basks in sunny clearings. Females guard their eggs until they hatch.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Common%20sun%20skink%20%28Eutropis%20multifasciata%29.jpg?width=1024"},{"name":"Oriental Garden Lizard","rarity":"common","id":"oriental-garden-lizard","subtitle":"Lizard","details":"A crested Asian agamid that changes colour with mood and season; breeding males flush red on the head and throat. It often perches on posts and walls.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Oriental%20garden%20lizard%20%28Calotes%20versicolor%29%20female%20head%20Bardia.jpg?width=1024"},{"name":"Peninsular Rock Agama","rarity":"common","id":"peninsular-rock-agama","subtitle":"Lizard","details":"An Indian rock agama of rocky hills and ruins. Breeding males turn striking combinations of red, orange and black. It basks prominently at midday.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Peninsular%20Rock%20agama%20-psammophilus%20dorsalis%20from%20Nilambur%20IMG%208938.jpg?width=1024"},{"name":"Red-headed Rock Agama","rarity":"common","id":"red-headed-rock-agama","subtitle":"Lizard","details":"A vivid African agama; dominant males wear a red-orange head and blue body. Subordinate males stay dull brown like females.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Agama%20agama%2053140442.jpg?width=1024"},{"name":"Starred Agama","rarity":"common","id":"starred-agama","subtitle":"Lizard","details":"A spiny Mediterranean agama, also called the hardun, that basks on walls and rocks and nods its head in display. It flattens itself against hot rock.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Agamidae%20Stellagama%20stellio%20picea%203.jpg?width=1024"},{"name":"Namaqua Chameleon","rarity":"common","id":"namaqua-chameleon","subtitle":"Lizard","details":"A desert chameleon of Namibia's Namib coast that digs into sand to escape heat and feeds on beetles in the fog-fed dunes.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Chamaeleo%20namaquensis%20110456308.jpg?width=1024"},{"name":"Common Chameleon","rarity":"common","id":"common-chameleon","subtitle":"Lizard","details":"The Mediterranean's chameleon, a slow, deliberate climber of shrubs and pines with independently swivelling eyes. It moves very slowly.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Chamaeleo%20chamaeleon%2010249090.jpg?width=1024"},{"name":"Common Frog","rarity":"common","id":"common-frog","subtitle":"Frog","details":"Europe's familiar brown frog, breeding in ponds in early spring. Its colour ranges from olive to russet with a dark eye mask.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/AD2009Sep15%20Rana%20temporaria%2001.jpg?width=1024"},{"name":"Moor Frog","rarity":"common","id":"moor-frog","subtitle":"Frog","details":"A small brown frog of European and Asian wetlands and meadows. In spring, breeding males briefly turn a striking sky blue.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Der%20blau%20Moorfrosch%20%28Rana%20arvalis%29%20bei%20der%20Paarung%20im%20Gew%C3%A4sser.jpg?width=1024"},{"name":"Agile Frog","rarity":"common","id":"agile-frog","subtitle":"Frog","details":"A slim, long-legged brown frog of European woodlands that makes huge leaps and breeds very early, sometimes in midwinter.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Agile%20frog%20%28Rana%20dalmatina%29.jpg?width=1024"},{"name":"Edible Frog","rarity":"common","id":"edible-frog","subtitle":"Frog","details":"A green water frog of European ponds and slow rivers, actually a hybrid of the pool and marsh frogs, basking at the water's edge.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Teichfrosch%20%28Pelophylax%20esculentus%29%20in%20Vegetationsdauerbeobachtungsfl%C3%A4che%20im%20Naturschutzgebiet%20Schwarzh%C3%B6lzl.jpg?width=1024"},{"name":"Pool Frog","rarity":"common","id":"pool-frog","subtitle":"Frog","details":"A small green water frog of Europe that prefers sunny, well-vegetated ponds and ditches, calling in rattling daytime choruses.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Bochum%20-%20Botanischer%20Garten%20-%20Pelophylax%20lessonae%2007%20ies.jpg?width=1024"},{"name":"Marsh Frog","rarity":"common","id":"marsh-frog","subtitle":"Frog","details":"The largest native European frog, a loud green water frog whose laughing chorus dominates ponds and marshes all summer long.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Marsh%20frog%20%28Pelophylax%20ridibundus%29.jpg?width=1024"},{"name":"Common Toad","rarity":"common","id":"common-toad","subtitle":"Toad","details":"A large, warty brown toad found across Europe, walking rather than hopping. It returns to the same breeding pond each spring.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Bufo%20bufo%20%2841731895194%29.jpg?width=1024"},{"name":"Japanese Common Toad","rarity":"common","id":"japanese-common-toad","subtitle":"Toad","details":"A sturdy, warty toad found across Japan, breeding in still ponds and flooded fields, with a low, short trilling night call.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Bufo%20japonicus%20formosus%20IMG%202717.JPG?width=1024"},{"name":"Asiatic Toad","rarity":"common","id":"asiatic-toad","subtitle":"Toad","details":"A large, warty toad common across East Asia, from farmland to forest edges, feeding at night on insects and other small prey.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Bufo%20gargarizans.jpg?width=1024"},{"name":"American Toad","rarity":"common","id":"american-toad","subtitle":"Toad","details":"A familiar warty toad of eastern North America with a long, musical trill. Its skin pattern ranges from brown to reddish.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Anaxyrus%20americanus%20-%20gwtstl%20-%20530563576.jpeg?width=1024"},{"name":"Southern Toad","rarity":"common","id":"southern-toad","subtitle":"Toad","details":"A stout toad of the southeastern coastal plain, with prominent knobs between its eyes, calling in a shrill trill from ditches.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Anaxyrus%20terrestris%20255599038.jpg?width=1024"},{"name":"Gulf Coast Toad","rarity":"common","id":"gulf-coast-toad","subtitle":"Toad","details":"A medium toad of the Gulf coastal plain with a dark-bordered pale back stripe, breeding in almost any still water after rain.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Incilius%20nebulifer%2C%20Gulf%20Coast%20Toad%2C%20Tamaulipas.jpg?width=1024"},{"name":"Western Toad","rarity":"common","id":"western-toad","subtitle":"Toad","details":"A stocky toad of western North America with a pale stripe down its back and no voice; males signal mainly by their movements.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Anaxyrus%20boreas12.JPG?width=1024"},{"name":"Canadian Toad","rarity":"common","id":"canadian-toad","subtitle":"Toad","details":"A small northern plains toad with a raised hump between its eyes, breeding in prairie potholes and shallow lake margins.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Canadian%20Toad%20-Anaxyrus%20hemiophrys.jpg?width=1024"},{"name":"European Tree Frog","rarity":"common","id":"european-tree-frog","subtitle":"Frog","details":"A small, smooth bright-green tree frog found across Europe, climbing reeds and shrubs and calling loudly from ponds at night.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/European%20Treefrog%20%28Hyla%20arborea%29.JPG?width=1024"},{"name":"Mediterranean Tree Frog","rarity":"common","id":"mediterranean-tree-frog","subtitle":"Frog","details":"A small green tree frog of the western Mediterranean, similar to its European cousin but with a shorter dark side stripe.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Hyla%20meridionalis%201.jpg?width=1024"},{"name":"Japanese Tree Frog","rarity":"common","id":"japanese-tree-frog","subtitle":"Frog","details":"A small green tree frog common across Japan, Korea and nearby mainland Asia, gathering in flooded rice fields to call at night.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Hyla%20japonica%20on%20leaf.JPG?width=1024"},{"name":"American Green Tree Frog","rarity":"common","id":"american-green-tree-frog","subtitle":"Frog","details":"A slender bright-green tree frog of the southeastern United States, with a pale side stripe and a loud, quonking night call.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Green%20treefrog.jpg?width=1024"},{"name":"Squirrel Treefrog","rarity":"common","id":"squirrel-treefrog","subtitle":"Frog","details":"A tiny, variable treefrog of the southeastern United States, named for its chattering, squirrel-like scolding daytime call.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/A%20squirrel%20treefrog%20%28Hyla%20squirella%29%20on%20a%20leaf%20%2893078228-df63-40de-bb06-b125d1038d98%29.JPG?width=1024"},{"name":"Gray Treefrog","rarity":"common","id":"gray-treefrog","subtitle":"Frog","details":"A mottled grey-green treefrog of eastern North America that changes colour to match bark, with bright orange hidden thighs.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Gray%20Tree%20Frog%20%28Hyla%20versicolor%29%20%288716723960%29.jpg?width=1024"},{"name":"Cuban Tree Frog","rarity":"common","id":"cuban-tree-frog","subtitle":"Frog","details":"The largest tree frog in North America, native to Cuba and nearby islands, with big toe pads and a rough, warty, mottled back.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Cuban%20tree%20frog%20%28Osteopilus%20septentrionalis%29%206.jpg?width=1024"},{"name":"Common Coqui","rarity":"common","id":"common-coqui","subtitle":"Frog","details":"A tiny brown frog of Puerto Rico famous for its loud two-note night call, 'ko-kee', heard all across the island's forests.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Eleutherodactylus%20coqui%20212490894.jpg?width=1024"},{"name":"Spring Peeper","rarity":"common","id":"spring-peeper","subtitle":"Frog","details":"A tiny tan treefrog of eastern North America with a dark X on its back. Its high peeping chorus is a first sign of spring.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Peter%20Paplanus%20-%20Spring%20Peeper%20%28Pseudacris%20crucifer%29%20%2844981664574%29.jpg?width=1024"},{"name":"Western Chorus Frog","rarity":"common","id":"western-chorus-frog","subtitle":"Frog","details":"A small striped frog of central North America whose rising, creaking spring call sounds like a thumbnail run along a comb.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Pseudacris%20triseriata01.jpg?width=1024"},{"name":"Crawfish Frog","rarity":"common","id":"crawfish-frog","subtitle":"Frog","details":"A plump, spotted prairie frog that lives in crayfish burrows across the central United States and calls from deep water.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/N%C3%B6rdlicher%20Krebsfrosch%20%28Lithobates%20areolatus%20circulosa%29%2C%20Kopf.jpg?width=1024"},{"name":"Pickerel Frog","rarity":"common","id":"pickerel-frog","subtitle":"Frog","details":"A neat, slender frog of eastern North America with two tidy rows of squarish dark spots between pale ridges along its back.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Lithobates%20palustris%2C%20Seitenansicht.jpg?width=1024"},{"name":"Green Frog","rarity":"common","id":"green-frog","subtitle":"Frog","details":"A green-brown pond frog of eastern North America whose short call sounds like a loose banjo string being plucked just once.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Green%20Frog%20%28Lithobates%20clamitans%29%20-%20Guelph%2C%20Ontario%2002.jpg?width=1024"},{"name":"Plains Leopard Frog","rarity":"common","id":"plains-leopard-frog","subtitle":"Frog","details":"A spotted Great Plains frog with pale, unbroken ridges along its back, breeding in marshes, stock ponds and slow streams.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Lithobates%20blairi.jpg?width=1024"},{"name":"Eastern Spadefoot","rarity":"common","id":"eastern-spadefoot","subtitle":"Toad","details":"A plump eastern toad with vertical pupils and black spades on its hind feet, emerging explosively after heavy summer rains.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Scaphiopus%20holbrookii%2C%20Seitenansicht.jpg?width=1024"},{"name":"Western Spadefoot","rarity":"common","id":"western-spadefoot","subtitle":"Toad","details":"A small spadefoot of California and Baja California grasslands, breeding in temporary rain pools with fast-growing tadpoles.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Spea%20hammondii%20284917875.jpg?width=1024"},{"name":"Couch's Spadefoot","rarity":"common","id":"couchs-spadefoot","subtitle":"Toad","details":"A greenish-yellow desert spadefoot of the southwest that can emerge, breed and rebury itself within a few nights of rain.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Couch%27s%20spadefoot%20toad%20%28scaphiopus%20couchii%29%20%2823204386211%29.jpg?width=1024"},{"name":"Plains Spadefoot","rarity":"common","id":"plains-spadefoot","subtitle":"Toad","details":"A small Great Plains spadefoot with a hard, dark spade on each hind foot, breeding explosively in rain-filled pools and ditches.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Plains%20Spadefoot%20%28Spea%20bombifrons%29%20%2814033958964%29.jpg?width=1024"},{"name":"Indian Flapshell Turtle","rarity":"common","id":"indian-flapshell-turtle","subtitle":"Turtle","details":"South Asian flapshell softshell of ponds and rivers, with fleshy flaps over its hind legs and spots across its olive shell.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Indian%20flapshell%20turtle%20%28Lissemys%20punctata%20punctata%29.jpg?width=1024"},{"name":"Chinese Softshell Turtle","rarity":"common","id":"chinese-softshell-turtle","subtitle":"Turtle","details":"Softshell turtle of East Asian rivers and lakes, with a flat leathery shell, long neck and a pointed, snorkel-like snout.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Pelodiscus%20sinensis%20332901222.jpg?width=1024"},{"name":"Balkan Pond Turtle","rarity":"common","id":"balkan-pond-turtle","subtitle":"Turtle","details":"Pond turtle of the eastern Mediterranean coasts and islands, with a dark keeled shell and pale network patterns on its neck and legs.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Balkanbeekschildpad%20-%20Balkan%20Terrapin%20-%20Mauremys%20rivulata%2003.jpg?width=1024"},{"name":"Japanese Pond Turtle","rarity":"common","id":"japanese-pond-turtle","subtitle":"Turtle","details":"Endemic pond turtle of Japan, with a rough brown keeled shell, serrated rear edge and dark spots along its pale plastron.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Mauremys%20japonica%20%28Japanese%20pond%20turtle%29.jpg?width=1024"},{"name":"Black Marsh Turtle","rarity":"common","id":"black-marsh-turtle","subtitle":"Turtle","details":"Black marsh turtle of Southeast Asia, its thick dark shell and broad head relieved by bold pale patches along the jaw and throat.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Sieben%20crass%20100118-0384%20stgd.jpg?width=800"},{"name":"Asian Leaf Turtle","rarity":"common","id":"asian-leaf-turtle","subtitle":"Turtle","details":"Leaf turtle of South and Southeast Asian streams, its brown shell shaped and coloured like a dead leaf on the forest floor.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Cycle%20denta%20100207-0654%20ipb.jpg?width=800"},{"name":"Keeled Box Turtle","rarity":"common","id":"keeled-box-turtle","subtitle":"Turtle","details":"Keeled box turtle of southern China and neighbouring countries, with three sharp shell keels and a strongly serrated rear edge.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Cuora%20mouhotii%2088505761.jpg?width=1024"},{"name":"Indian Roofed Turtle","rarity":"common","id":"indian-roofed-turtle","subtitle":"Turtle","details":"Roofed turtle of northern South Asian rivers, named for the raised, tent-like ridge running along the middle of its shell.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Pangshura%20tecta%20258210952.jpg?width=1024"},{"name":"Assam Roofed Turtle","rarity":"common","id":"assam-roofed-turtle","subtitle":"Turtle","details":"Roofed turtle of northeastern India and Bangladesh riverbanks, with a high spiked keel and arrow-like mark behind its head.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Pangshura%20sylhetensis%20176449534.jpg?width=1024"},{"name":"Florida Cooter","rarity":"common","id":"florida-cooter","subtitle":"Turtle","details":"Large basking cooter of Florida lakes and marshes, with a dark olive shell bearing pale hairpin markings on its second scute.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Florida%20Cooter%20on%20Stump%20%2812912698265%29.jpg?width=800"},{"name":"Northern Red-bellied Cooter","rarity":"common","id":"northern-red-bellied-cooter","subtitle":"Turtle","details":"River cooter of the eastern United States, named for the reddish tint of its smooth lower shell, with a notched upper jaw beak.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Pseudemys%20rubriventris%20basking%20northern%20red%20bellied%20crooters%20turtles.jpg?width=1024"},{"name":"False Map Turtle","rarity":"common","id":"false-map-turtle","subtitle":"Turtle","details":"Map turtle of large central United States rivers, with fine map-like shell lines and a pale crescent mark behind each eye.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Falsche%20Landkarten-H%C3%B6ckerschildkr%C3%B6te%20%28Graptemys%20pseudogeographica%29%2C%20Vorderansicht.jpg?width=1024"},{"name":"Common Map Turtle","rarity":"common","id":"common-map-turtle","subtitle":"Turtle","details":"Map turtle of eastern North American lakes and slow rivers, its olive shell etched with fine pale lines like a contour map.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Northern%20Map%20Turtle%2C%20sunning.jpg?width=1024"},{"name":"Ouachita Map Turtle","rarity":"common","id":"ouachita-map-turtle","subtitle":"Turtle","details":"Map turtle of the Mississippi and Ouachita rivers, with rectangular blotches below its eyes and bold dark shell markings.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Ouachita-H%C3%B6ckerschildkr%C3%B6te%20%28Graptemys%20ouachitensis%29%2C%20Oberseite.jpg?width=1024"},{"name":"Western Pond Turtle","rarity":"common","id":"western-pond-turtle","subtitle":"Turtle","details":"The only native pond turtle of the Pacific coast of North America, with a marbled olive shell and dark-speckled pale legs.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Actinemys%20marmorata05.jpg?width=1024"},{"name":"Texas Tortoise","rarity":"common","id":"texas-tortoise","subtitle":"Tortoise","details":"Small tortoise of Texas and northeastern Mexico dry scrub, with a patterned brown shell and dark rings on its front legs.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Gopherus%20berlandieri%2C%20Texas%20Tortoise%2C%20Tamaulipas.jpg?width=1024"},{"name":"Russian Tortoise","rarity":"common","id":"russian-tortoise","subtitle":"Tortoise","details":"Steppe tortoise of Central Asia, with a rounded yellow-brown shell, four claws on each front foot and long winter burrows.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Testudo%20horsfieldii%20Dzhudabulok.jpg?width=1024"},{"name":"Bell's Hinge-back Tortoise","rarity":"common","id":"bells-hinge-back-tortoise","subtitle":"Tortoise","details":"Hinge-back tortoise of sub-Saharan African savannas, closing the hinged rear of its tall patterned shell down over its hind legs.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Kinixys%20belliana%20219976203.jpg?width=800"},{"name":"Yellow-footed Tortoise","rarity":"common","id":"yellow-footed-tortoise","subtitle":"Tortoise","details":"Large forest tortoise of the Amazon basin, with a dark elongated shell, yellow-orange leg scales and yellow scute centres.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Chelonoidis%20denticulatus%20in%20Ouwehands%20Dierenpark.jpg?width=1024"},{"name":"Chaco Tortoise","rarity":"common","id":"chaco-tortoise","subtitle":"Tortoise","details":"Tortoise of dry plains in Argentina, Bolivia and Paraguay, with a tan domed shell whose broad scutes show clear pale growth rings.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Argentine%20Tortoise%20%28Chelonoidis%20chilensis%29.JPG?width=1024"},{"name":"Elongated Tortoise","rarity":"common","id":"elongated-tortoise","subtitle":"Tortoise","details":"Yellowish tortoise of South and Southeast Asian hill forests, its long elongated shell marked with dark blotches on each scute.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Elongated%20Tortoise%20%28Indotestudo%20elongata%29%20-%20Thailand%201.jpg?width=1024"},{"name":"Impressed Tortoise","rarity":"common","id":"impressed-tortoise","subtitle":"Tortoise","details":"Impressed tortoise of Southeast Asian hill forests, its pale brown shell scutes sunken in the centre with raised, darkened edges.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Manouria%20impressa%20specimen.jpg?width=1024"},{"name":"New Guinea Crocodile","rarity":"common","id":"new-guinea-crocodile","subtitle":"Crocodile","details":"A medium crocodile of New Guinea's river swamps and grasslands, reaching about 3.5 metres, active mainly after dark near the water.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Buaya%20Irian%20Crocodylus%20novaeguineae%20Bandung%20Zoo%202.JPG?width=1024"},{"name":"Congo Dwarf Crocodile","rarity":"common","id":"congo-dwarf-crocodile","subtitle":"Crocodile","details":"A small dwarf crocodile of Congo Basin rainforest pools and swamps, reaching about 1.5 metres, with a short snout and dark markings.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Osteolaemus%20osborni%20107154504.jpg?width=1024"},{"name":"Central African Slender-snouted Crocodile","rarity":"common","id":"central-african-slender-snouted-crocodile","subtitle":"Crocodile","details":"A slender-snouted crocodile of Central African forest rivers, reaching about 3 metres, with smooth scales and a fish-eating diet.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Mecistops%20leptorhynchus%20249206905.jpg?width=1024"},{"name":"Broad-snouted Caiman","rarity":"common","id":"broad-snouted-caiman","subtitle":"Caiman","details":"A medium caiman of South American marshes and slow rivers, reaching about 3 metres, named for its exceptionally broad, rounded snout.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Jacar%C3%A9-de-papo-amarelo%20%28Caiman%20latirostris%29.jpg?width=1024"},{"name":"Yacare Caiman","rarity":"common","id":"yacare-caiman","subtitle":"Caiman","details":"A medium caiman of the Pantanal and other South American wetlands, reaching about 3 metres, often seen basking in large groups.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Caiman%20yacare%20Pantanal.jpg?width=1024"},{"name":"Cuvier's Dwarf Caiman","rarity":"common","id":"cuviers-dwarf-caiman","subtitle":"Caiman","details":"The smallest caiman in the Americas, from Amazon and Orinoco streams, reaching about 1.5 metres, with a dome-shaped, smooth forehead.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Paleosuchus%20palpebrosus.jpg?width=1024"},{"name":"Schneider's Dwarf Caiman","rarity":"common","id":"schneiders-dwarf-caiman","subtitle":"Caiman","details":"A small dwarf caiman of Amazon forest streams, reaching about 2 metres, with a triangular head and rough, heavily ridged scales.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Ca%C3%AFman%20de%20Schneider%20%28Paleosuchus%20trigonatus%29.jpg?width=1024"},{"name":"West African Crocodile","rarity":"common","id":"west-african-crocodile","subtitle":"Crocodile","details":"A crocodile of West African rivers, lagoons and inland wetlands, reaching about 4 metres, long confused with its close Nile relative.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Crocodylus%20suchus%2078409213.jpg?width=1024"},{"name":"Blue-spotted Salamander","rarity":"common","id":"blue-spotted-salamander","subtitle":"Salamander","details":"A dark mole salamander flecked with pale blue spots, it lives in moist woodlands and vernal pools of northeastern North America.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Ambystoma%20laterale%20150008446.jpg?width=1024"},{"name":"Jefferson Salamander","rarity":"common","id":"jefferson-salamander","subtitle":"Salamander","details":"A slender, grey-brown mole salamander of eastern North American forests, among the first amphibians to breed as winter snows melt.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Ambystoma%20jeffersonianum.jpg?width=1024"},{"name":"Eastern Newt","rarity":"common","id":"eastern-newt","subtitle":"Newt","details":"This North American newt has three lives: an aquatic larva, a bright orange land-dwelling eft, and an olive-green aquatic adult.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Notophthalmus%20viridescens%20adult%20female.jpg?width=1024"},{"name":"California Newt","rarity":"common","id":"california-newt","subtitle":"Newt","details":"An orange-bellied newt of California streams and woodlands, breeding males return to the same quiet pools and slow stream reaches.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Taricha%20torosa%2C%20Napa%20County%2C%20CA.jpg?width=1024"},{"name":"Smooth Newt","rarity":"common","id":"smooth-newt","subtitle":"Newt","details":"A small, widespread European newt; breeding males develop a wavy crest, spotted flanks and a bright orange stripe along the belly.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/LissotritonVulgarisMaleWater.JPG?width=1024"},{"name":"Alpine Newt","rarity":"common","id":"alpine-newt","subtitle":"Newt","details":"A colourful European mountain newt; breeding males turn blue along the flanks with a low, spotted crest and an orange belly.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Bergmolch%20Alpenmolch%20Ichthyosaura%20alpestris.jpg?width=1024"},{"name":"Marbled Newt","rarity":"common","id":"marbled-newt","subtitle":"Newt","details":"A large green-and-black marbled newt of western European ponds and woodlands, named for the swirling pattern across its back.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Triturus%20marmoratus.JPG?width=1024"},{"name":"Himalayan Crocodile Newt","rarity":"common","id":"himalayan-crocodile-newt","subtitle":"Newt","details":"A rough-skinned, orange-marked newt of highland wetlands from Nepal to Vietnam, named for the bumpy ridges along its head and back.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Tylototriton%20verrucosus.jpg?width=1024"},{"name":"Ensatina","rarity":"common","id":"ensatina","subtitle":"Salamander","details":"A lungless woodland salamander of western North America that breathes through its skin and the lining of its mouth and throat.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Ensatina%20eschscholtzii%20%2825009704736%29.jpg?width=1024"},{"name":"Red Salamander","rarity":"common","id":"red-salamander","subtitle":"Salamander","details":"A stout, bright red salamander with black spots, found under logs and stones along clear streams in the eastern United States.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Pseudotriton%20ruber%20-%20Red%20Salamander.jpg?width=1024"},{"name":"Red-backed Salamander","rarity":"common","id":"red-backed-salamander","subtitle":"Salamander","details":"A tiny lungless salamander, usually with a chestnut stripe down its back, it is one of the most abundant forest salamanders in the east.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Plethodon%20cinereus1.jpg?width=1024"},{"name":"Slimy Salamander","rarity":"common","id":"slimy-salamander","subtitle":"Salamander","details":"A large, glossy black woodland salamander flecked with silver-white spots, named for the sticky skin secretions it produces.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Plethodon%20glutinosus%20337527550.jpg?width=1024"},{"name":"Ringed Caecilian","rarity":"common","id":"ringed-caecilian","subtitle":"Caecilian","details":"A limbless South American caecilian that burrows through forest soil, its dark body ringed with pale bands from nose to tail.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Siphonops%20annulatus.jpg?width=1024"},{"name":"Cayenne Caecilian","rarity":"common","id":"cayenne-caecilian","subtitle":"Caecilian","details":"A fully aquatic South American caecilian that swims like an eel through slow rivers and flooded forests of the Amazon basin.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Typhlonectes%20compressicauda%202.jpg?width=1024"}];
  extra.forEach(function (x) {
    if (S.byId.has(x.id)) return;
    var c = { id: x.id, num: S.cards.length + 1, name: x.name, rarity: x.rarity,
              subtitle: x.subtitle, details: x.details, image: x.image, logo: '' };
    S.cards.push(c);
    S.byId.set(c.id, c);
    if (S.pools[c.rarity]) S.pools[c.rarity].push(c);
  });
})();
